    func folder(id: String)  -> Folder?
    
    func forecastSelectedDay()  -> String?
    
    func importJson(text: String) throws 
    
    /**
     * Indent: make each task the last child of its previous sibling (Cmd-]).
     */
    func indent(ids: [String]) 
    
    func markReviewed(ids: [String]) 
    
    func moveFolder(id: String, parent: String?, after: String?) 
    
    func moveProject(id: String, folder: String?, after: String?) 
    
    func moveTag(id: String, parent: String?, after: String?) 
    
    /**
     * Move task(s) under a new parent (project/task/null=inbox) at the end,
     * or after a sibling.
     */
    func moveTasks(ids: [String], parent: String?, after: String?) 
    
    /**
     * Outdent: move a task after its parent, under the grandparent (Cmd-[).
     */
    func outdent(ids: [String]) 
    
    func perspective()  -> Perspective
    
    func project(id: String)  -> Project?
    
    func projectInfo(id: String)  -> ProjectInfo?
    
    /**
     * All remaining projects in sidebar order (for pickers and Quick Open).
     */
    func projectList()  -> [ProjectListEntry]
    
    func redo()  -> Bool
    
    func rename(id: String, name: String) 
    
    func resetEmpty() 
    
    func resetToTutorial() 
    
    /**
     * Quick Open: folders, projects and tags matching `q`.
     */
    func searchItems(q: String)  -> [SearchResult]
    
    func setCollapsed(key: String, collapsed: Bool) 
    
    func setCompletedByChildren(id: String, v: Bool) 
    
    func setEstimate(id: String, minutes: UInt32?) 
    
    func setFocus(ids: [String]) 
    
    func setFolderStatus(id: String, status: FolderStatus) 
    
    func setForecastSelectedDay(day: String?) 
    
    func setItemDates(id: String, `defer`: Int64?, planned: Int64?, due: Int64?) 
    
    func setItemTags(id: String, tagIds: [String]) 
    
    func setNote(id: String, note: String) 
    
    func setPerspective(p: Perspective) 
    
    func setProjectStatus(id: String, status: ProjectStatus) 
    
    func setProjectType(id: String, t: ProjectType) 
    
    func setRepetition(id: String, rule: RepetitionRule?) 
    
    func setReviewInterval(id: String, iv: ReviewInterval) 
    
    func setSequential(id: String, sequential: Bool) 
    
    /**
     * Sidebar expansion uses "sb:"-prefixed keys; default is expanded.
     */
    func setSidebarExpanded(key: String, expanded: Bool) 
    
    func setSidebarSelection(ids: [String]) 
    
    func setTagAllowsNextAction(id: String, v: Bool) 
    
    func setTagStatus(id: String, status: TagStatus) 
    
    func setViewOptions(vo: ViewOptions) 
    
    func settings()  -> Settings
    
    func sidebar()  -> SidebarModel
    
    func tag(id: String)  -> Tag?
    
    /**
     * All tags in hierarchical order (for pickers).
     */
    func tagList()  -> [TagListEntry]
    
    func task(id: String)  -> Task?
    
    func taskInfo(id: String)  -> TaskInfo?
    
    /**
     * Re-emit so time-dependent display (due soon / deferred) refreshes.
     */
    func tick() 
    
    /**
     * Mark complete (creating the next repetition when applicable).
     * Toggles back to incomplete if already complete.
     */
    func toggleComplete(ids: [String]) 
    
    func toggleFlag(ids: [String]) 
    
    func undo()  -> Bool
    
    func updateSettings(s: Settings) 
    
    func viewOptions()  -> ViewOptions
    
}
