    typealias SwiftType = DueState

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DueState {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .none
        
        case 2: return .dueSoon
        
        case 3: return .overdue
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DueState, into buf: inout [UInt8]) {
        switch value {
        
        
        case .none:
